import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/software-exam/ispm/project-scope-management/comprehensive-exercises/","title":"10 综合练习 | 软考","lang":"zh-CN","frontmatter":{"title":"10 综合练习","createTime":"2026-11-22T21:20:00.000Z","permalink":"/software-exam/ispm/project-scope-management/comprehensive-exercises/","outline":false,"aside":false},"readingTime":{"minutes":106.2,"words":31859},"git":{"createdTime":1795354081000},"filePathRelative":"software-exam/ispm/project-scope-management/10.comprehensive-exercises.md","headers":[],"bulletin":false}`),a={name:`10.comprehensive-exercises.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="exam-note"><p><a id="q1" class="quiz-anchor"></a></p><p><strong>1.</strong> 项目范围是否完成和产品范围是否完成分别以（ ）作为衡量标准。</p><ul><li>A．项目管理计划，产品需求</li><li>B．范围说明书，WBS</li><li>C．范围基线，范围定义</li><li>D．合同，工作说明书</li></ul><details class="quiz" data-q="1" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：产品范围：指某项产品、服务或成果所具有的特征和功能。产品范围的完成情况是根据产品需求来衡量的。项目范围：包括产品范围，是为交付具有规定特性与功能的产品、服务或成果而必须完成的工作（P272）　<span class="quiz-src">自编</span></p></details><p><a id="q2" class="quiz-anchor"></a></p><p><strong>2.</strong> （ ）是指某项产品、服务或成果所具有的特征和功能，其完成情况依据（ ）来衡量；而（ ）涵盖前者，是为交付相应成果必须完成的工作，其完成情况依据（ ）来衡量。</p><ul><li>A．产品范围、产品需求、项目范围、项目管理计划</li><li>B．项目范围、产品需求、产品范围、项目管理计划</li><li>C．产品范围、项目管理计划、项目范围、产品需求</li><li>D．项目范围、项目管理计划、产品范围、产品需求</li></ul><details class="quiz" data-q="2" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：产品范围：指某项产品、服务或成果所具有的特征和功能。产品范围的完成情况是根据产品齿求采德量的。项目范围：包括产品范围，是为交付具有规定特性与功能的产品、服务或成果而必须完成的工作（P272）　<span class="quiz-src">自编</span></p></details><p><a id="q3" class="quiz-anchor"></a></p><p><strong>3.</strong> 项目范围管理中，“范围”有两种含义，其中（ ）指某项产品、服务或成果所具有的特征和功能，其完成情况根据（ ）来衡量；（ ）完成情况根据项目管理计划来衡量。</p><ul><li>A．产品范围、产品需求、项目范围</li><li>B．项目范围、产品需求、产品范围</li><li>C．产品范围、项目管理计划、项目范围</li><li>D．项目范围、项目管理计划、产品范围</li></ul><details class="quiz" data-q="3" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：在项目环境中，“范围”包含两种含义：产品范围指某项产品、服务或成果所具有的特征和功能，其完成情况是根据产品需求来衡量的：项目范围包括产品范围，是为交付具有规定特性与功能的产品、服务或成果面必须完成的工作，其完成情况是根据项目管理计划来衡量的（P272）　<span class="quiz-src">自编</span></p></details><p><a id="q4" class="quiz-anchor"></a></p><p><strong>4.</strong> 项目范围管理的目的是（ ）。</p><ul><li>A．识别、获取和管理所需资源以成功完成项目</li><li>B．识别、定义、组合项目管理过程中的各个过程和活动</li><li>C．确保项目信息及时且恰当地规划、收集、控制和最终处置</li><li>D．确保项目做且只做所需的全部工作以成功完成项目</li></ul><details class="quiz" data-q="4" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目范围管理包括确保项目做且只做所需的全部工作，以成功完成项目。项目范围管理主要在于定义和控制哪些工作应该包括在项目内，哪些不应该包含在项目内（P272）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q5" class="quiz-anchor"></a></p><p><strong>5.</strong> 需求一直是项目管理的关注重点，需求管理过程结束于（ ），即把产品、服务或成果移交给接收方，以便长期测量、监控、实现并维持收益。</p><ul><li>A．阶段验收</li><li>B．需求回溯</li><li>C．范围确认</li><li>D．需求关闭</li></ul><details class="quiz" data-q="5" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：需求一直是项目管理的关注重点，盖求管理过程结束于需求关闭，即把产品、服务或成果移交给接收方，以便长期测量、监控、实现并维持收益（P272）　<span class="quiz-src">自编</span></p></details><p><a id="q6" class="quiz-anchor"></a></p><p><strong>6.</strong> 需要在整个项目期间定期开展的过程是（ ）。</p><ul><li>A．定义范围</li><li>B．创建WBS</li><li>C．确认范围</li><li>D．控制范围</li></ul><details class="quiz" data-q="6" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：规划范围管理：仅开展一次或仅在项目的预定义时开展；收集需求：仅开展一次或仅在项目的预定义时开展；定义范围：需要在整个项目期间反复开展；创建 WBS:仅开展一次或仅在项目的预定义时开展；确认范用：需要在整个项目期间定期开展；控制范围：需要在整个项目期间反复开展；（P272-273）　<span class="quiz-src">自编</span></p></details><p><a id="q7" class="quiz-anchor"></a></p><p><strong>7.</strong> 描述产品、服务或成果的边界和验收标准，属于（ ）过程的作用。</p><ul><li>A．收集需求</li><li>B．确认范围</li><li>C．规划范围管理</li><li>D．定义范围</li></ul><details class="quiz" data-q="7" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：定义范围作用：描述产品、服务或成果的边界和验收标准（P273）　<span class="quiz-src">自编</span></p></details><p><a id="q8" class="quiz-anchor"></a></p><p><strong>8.</strong> （ ）不属于范围管理的过程。</p><ul><li>A．规划范围管理</li><li>B．收集需求</li><li>C．定义范围</li><li>D．控制资源</li></ul><details class="quiz" data-q="8" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制资源属于资源管理的过程（P273）　<span class="quiz-src">2023 年下半年高项第 1 批</span></p></details><p><a id="q9" class="quiz-anchor"></a></p><p><strong>9.</strong> 范围管理裁剪时需要考虑的因素不包括（ ）。</p><ul><li>A．知识和需求管理</li><li>B．雷求的稳定性</li><li>C．治理</li><li>D．WBS的层级</li></ul><details class="quiz" data-q="9" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：范围裁剪时应考虑的因素包括：(1)知识和需求管理；(2)确认和控制；(3)开发方法(4)需求的稳定性；(5)治理（P274）　<span class="quiz-src">自编</span></p></details><p><a id="q10" class="quiz-anchor"></a></p><p><strong>10.</strong> 范围管理中，需要裁剪的考虑因素不包括（ ）。</p><ul><li>A．知识和需求管理</li><li>B．确认和控制</li><li>C．开发方法</li><li>D．WBS的结构</li></ul><details class="quiz" data-q="10" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：范围裁剪时应考虑的因素包括：(1)知识和需求管理；(2)确认和控制；(3)开发方法(4)需求的稳定性；(5)治理（P274）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q11" class="quiz-anchor"></a></p><p><strong>11.</strong> 在（ ）生命周期中，项目开始时就对项目可交付成果进行定义，对任何范围变化都要进行变更管理。</p><ul><li>A．预测型</li><li>B．适应型</li><li>C．敏捷型</li><li>D．迭代型</li></ul><details class="quiz" data-q="11" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：在预测型项目中，经过批准的项目范围说明书、工作分解结构(WBS)和相应的WBS词典构成项目范围基准。只有通过正式变更控制程序，才能进行基准变更（P274）　<span class="quiz-src">教材第 9 章章节习题</span></p></details><p><a id="q12" class="quiz-anchor"></a></p><p><strong>12.</strong> 以下关于范围管理的说法错误的是（ ）。</p><ul><li>A．在敏捷型生命周期中，范围会在整个项目期间被定义和再定义</li><li>B．在敏捷型生命周期中，在每次选代中，都会重复开展两个过程：①确认范围；②控制范田</li><li>C．需求比较明确、变化不大的情况适合采用敏捷型开发方法</li><li>D．在预测型项目中，经过批准的项目范围说明书、工作分解结构(WBS)和相应的WBS词典构成项目范围基准</li></ul><details class="quiz" data-q="12" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：采用敏捷或适应型生命周期，旨在应对大量变更，需要干系人持续参与项目。而需求比较明确、变化不大的项目，应采用预测型（瀑布型）开发方法，敏捷方法反而不适用，所以C错误（P274）　<span class="quiz-src">自编</span></p></details><p><a id="q13" class="quiz-anchor"></a></p><p><strong>13.</strong> 在预测型生命周期中，在开展确认范围、控制范围及其他控制过程时，（ ）被用作比较的基础</p><ul><li>A．基准</li><li>B．未完成项</li><li>C．WBS</li><li>D．需求跟踪矩阵</li></ul><details class="quiz" data-q="13" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：在预测型生命周期中，在开展确认范围、控制范围及其他控制过程时，基准被用作比较的基础（P274）　<span class="quiz-src">自编</span></p></details><p><a id="q14" class="quiz-anchor"></a></p><p><strong>14.</strong> 采用适应型生命周期的项目，在开展确认范围、控制范围及其他控制过程时，使用（ ）反映当前需求。</p><ul><li>A．范团基准</li><li>B．项目范围</li><li>C．WBS</li><li>D．未完成项</li></ul><details class="quiz" data-q="14" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：采用适应型生命周期的项目，则使用未完成项（包括产品需求和用户故事）反肤当前需求（P274）　<span class="quiz-src">自编</span></p></details><p><a id="q15" class="quiz-anchor"></a></p><p><strong>15.</strong> 关于确认范围的描述，正确的是（ ）。</p><ul><li>A．确认范围过程的输入是控制质量过程输出的核实的可交付成果</li><li>B．验收的可交付成果不需要获得授权干系人的签字批准</li><li>C．干系人仅需在项目规划阶段介入，无需参与启动阶段</li><li>D．确认范围过程的输出是控制质量过程的输入</li></ul><details class="quiz" data-q="15" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：确认范围是正式验收已完成的项目可交付成果的过程。从控制质量过程输出的核实的可交付成果是确认范围过程的输入，而验收的可交付成果是确认范围过程的输出之一，由获得授权的干系人正式签字批准（P274）　<span class="quiz-src">自编</span></p></details><p><a id="q16" class="quiz-anchor"></a></p><p><strong>16.</strong> 关于项目范围管理过程的描述不正确的是（ ）。</p><ul><li>A．采用敏捷或适应型生命周期，旨在应对大量变更，需要干系人持续参与项目</li><li>B．在预测型项目中，只有通过正式变更控制程序才能变更项目范围基准</li><li>C．在预测型项目中，通过多次选代来开发可交付成果，使用未完成项反映当前需求</li><li>D．在适应型或敏捷型生命周期中，在每次选代开始时都可以定义或批准详细的范围</li></ul><details class="quiz" data-q="16" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在预测型项目中，经过批准的项目范围说明书、工作分解结构(WBS)和相应的WBS词典构成项目范围基准。只有通过正式变更控制程序，才能进行基准变更采用适应型生命周期的项目，则使用未完成项（包括产品需求和用户故事）反肤当前蛋求（P274）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q17" class="quiz-anchor"></a></p><p><strong>17.</strong> 采用敏捷或适应型生命周期，在一个选代开始时，团队将努力确定产品未完成项中，哪些优先级高的未完成项需要在下一次选代中交付。在每次选代中，都会重复开展的过程包括（ ）①收集需求；②定义范围；③规划范围管理；④创建WBS</p><ul><li>A．①②③</li><li>B．C3④</li><li>C．①②④</li><li>D．①③④</li></ul><details class="quiz" data-q="17" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：采用敏捷或适应型生命周期，旨在应对大量变更，需要干系人持续参与项目。因此，应将适应型项目的整体范围分解为一系列拟实现的需求和拟执行的工作（有时称为产品未完成项），通过多次送代来开发可交付成果，并在每次选代开始时定义和批准详细的范围（P274）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q18" class="quiz-anchor"></a></p><p><strong>18.</strong> （ ）不是规划范围管理过程的输入。</p><ul><li>A．项目章程</li><li>B．项目管理计划</li><li>C．质量管理计划</li><li>D．需求管理计划</li></ul><details class="quiz" data-q="18" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：盖求管理计划是规划范围管理过程的输出。规划范围管理过程的输入：1.项目章程；2.项目管理计划（质量管理计划、项目生命周期描述、开发方法）;3.事业环境因素；4.组织过程资产（P275）　<span class="quiz-src">教材第 9 章章节习题</span></p></details><p><a id="q19" class="quiz-anchor"></a></p><p><strong>19.</strong> 规划范围管理需要参考项目管理计划中的（ ）。</p><ul><li>A．项目生命周期描述</li><li>B．风险管理计划</li><li>C．干系人登记册</li><li>D．进度管理计划</li></ul><details class="quiz" data-q="19" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：规划范围管理中使用的项目管理计划组件主要包括：·质量管理计划：在项目中实施组织的质量政策、方法和标准的方式会影响管理项目和产品范围的方式（P275）　<span class="quiz-src">自编</span></p></details><p><a id="q20" class="quiz-anchor"></a></p><p><strong>20.</strong> 范围管理计划中不包含（ ）。</p><ul><li>A．制定项目范围说明书</li><li>B．确定如何审批和维护范围基准</li><li>C．正式验收已完成的项目可交付成果</li><li>D．确定可交付成果的正确性</li></ul><details class="quiz" data-q="20" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：范围管理计划用于指导如下过程和相关工作：①制定项目范围说明书；②根据详细项目范围说明书创建WBS;③确定如何审批和维护范围基准；④正式验收已完成的项目可交付成果（P276）　<span class="quiz-src">自编</span></p></details><p><a id="q21" class="quiz-anchor"></a></p><p><strong>21.</strong> 需求管理计划是项目管理计划的组成部分，其内容不包括（ ）。</p><ul><li>A．如何规划、跟踪和报告各种需求活动</li><li>B．配置管理活动</li><li>C．测量指标及使用这些指标的理由</li><li>D．如何定义和分解范围</li></ul><details class="quiz" data-q="21" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：需求管理计划是项目管理计划的组成部分，主要内容包括：①如何规划、跟踪和报告各种盖求活动；②配置管理活动，例如，如何启动变更，如何分析其影响，如何进行追湖、跟踪和报告，以及变更审批权限；◎需求优先级排序过程；④测量指标及使用这些指标的理由；⑤反欧哪些需求属性将被列入跟踪矩阵等（P276）　<span class="quiz-src">自编</span></p></details><p><a id="q22" class="quiz-anchor"></a></p><p><strong>22.</strong> 关于范围管理计划的描述，不正确的是（ ）。</p><ul><li>A．包括需求优先级排序过程</li><li>B．包括制定项目范围说明书</li><li>C．规定了正式验收已完成的项目可交付成果</li><li>D．规定了根据详细项目范围说明书创建WBS</li></ul><details class="quiz" data-q="22" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A属于需求管理计划的内容。范围管理计划用于指导如下过程和相关工作：①制定项目范围说明书；②根据详细项目范围说明书创建WBS;③确定如何审批和维护范围基准：④正式验收已完成的项目可交付成果（P276）　<span class="quiz-src">自编</span></p></details><p><a id="q23" class="quiz-anchor"></a></p><p><strong>23.</strong> （ ）是规划范围管理的工具和技术，可用于评估、收集需求，详述项目和产品范围，创造产品等各种方法。</p><ul><li>A．备选方案分析</li><li>B．趋势分析</li><li>C．偏差分析</li><li>D．回归分析</li></ul><details class="quiz" data-q="23" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：适用于规划范围管理过程的数据分析技术是备选方案分析。该技术用于评估、收集需求，详述项目和产品范围，创造产品，确认范围和控制范围的各种方法（P276）　<span class="quiz-src">自编</span></p></details><p><a id="q24" class="quiz-anchor"></a></p><p><strong>24.</strong> 以下描述中，属于范围管理计划的作用的是（ ）。</p><ul><li>A．指导创建WBS并确定范围基准</li><li>B．需求优先级排序过程</li><li>C．反映哪些需求属性将被列入跟踪矩阵</li><li>D．如何规划、跟踪和报告各种需求活动</li></ul><details class="quiz" data-q="24" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：范围管理计划是项目管理计划的组成部分，描述将如何定义、制定、监督、控制和确认项目范围。范围管理计划用于指导如下过程和相关工作：①制定项目范围说明书；（2根据详细项目范围说明书创建 WBS;“③）确定如何审批和维护范围基准：④正式验收已完成的项目可交付成果（P276）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q25" class="quiz-anchor"></a></p><p><strong>25.</strong> 关于需求管理计划不正确的是（ ）。</p><ul><li>A．反映需求属性将被列入跟踪矩阵</li><li>B．记录规划、跟踪和报告各种需求活动</li><li>C．记录优先级排序过程</li><li>D．指导如何审批和维护范围基准</li></ul><details class="quiz" data-q="25" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：需求管理计划是项目管理计划的组成部分，描述如何分析、记录和管理需求。包括：①如何规划、跟踪和报告各种需求活动；②配置管理活动，例如，如何启动变更，如何分析其影响，如何进行道湖、限踪和报告，以及变更审批权限；③需求优先级排序过程；④测量指标及使用这些指标的理由；⑤反映哪些需求属性将被列入跟踪矩阵等（P276）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q26" class="quiz-anchor"></a></p><p><strong>26.</strong> 规划范围管理的输出是（ ）。</p><ul><li>A．需求管理计划</li><li>B．项目管理计划</li><li>C．质量管理计划</li><li>D．开发方法</li></ul><details class="quiz" data-q="26" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：规划范围管理过程的主要输入为项目管理计划，主要输出为范围管理计划和需求管理计划（P276）　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q27" class="quiz-anchor"></a></p><p><strong>27.</strong> 规划范围管理是为记录如何（ ）项目范围及产品范围而创建范围管理计划的过程</p><ul><li>A．定义、确认和控制</li><li>B．定义、确认和验证</li><li>C．识别、管理和控制</li><li>D．识别、管理和确认</li></ul><details class="quiz" data-q="27" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：规划范围管理是为了记录如何定义、确认和控制项目范围及产品范围，面创建范围管理计划的过程（P275）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q28" class="quiz-anchor"></a></p><p><strong>28.</strong> 规划范围管理的输入不包括（ ）。</p><ul><li>A．质量管理计划</li><li>B．项目生命周期描述</li><li>C．范围管理计划</li><li>D．开发方法</li></ul><details class="quiz" data-q="28" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：范围管理计划是规划范围管理的输出（P275-276）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q29" class="quiz-anchor"></a></p><p><strong>29.</strong> 当用户提出新需求时，项目组应在（ ）指导下进行项目范围管理。</p><ul><li>A．WBS</li><li>B．范围管理计划</li><li>C．项目范围说明书</li><li>D．需求跟踪矩阵</li></ul><details class="quiz" data-q="29" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：范围管理计划描述将如何定义、监督、控制和确认项目范围范围管理计划用于指导如下过程和相关工作：①制定项目范围说明书；②根据详细项目范围说明书创建WBS;③确定如何审批和维护范围基准；④正式验收已完成的项目可交付成果（P275）　<span class="quiz-src">2022 年下半年高项</span></p></details><p><a id="q30" class="quiz-anchor"></a></p><p><strong>30.</strong> 适用于规划范围管理的数据分析技术是（ ），用于评估、收集需求，详述项目和产品范围，创造产品，确认范围和控制范围的各种方法。</p><ul><li>A．备选方案分析</li><li>B．趋势分析</li><li>C．根本原因分析</li><li>D．偏差分析</li></ul><details class="quiz" data-q="30" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：适用于规划范围管理的数据分析技术是备选方案分析。备选方案分析技术用于评估、收集需求，详述项目和产品范围，创造产品，确认范围和控制范围的各种方法（P276）　<span class="quiz-src">2023 年下半年高项第 3 批</span></p></details><p><a id="q31" class="quiz-anchor"></a></p><p><strong>31.</strong> 关于范围管理的描述，正确的是（ ）。</p><ul><li>A．定义范围管理是为了记录如何定义、确认和控制项目范围及产品范围，而创建范围管理计划的过程</li><li>B．范围管理计划包含配置管理活动和需求优先级排序过程</li><li>C．范围管理计划是非常详细的正式的计划</li><li>D．规划范围管理的作用是在整个项目期间对如何管理范围提供指南和方向</li></ul><details class="quiz" data-q="31" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：选项A错误。定义范围是制定项目和产品详细描述的过程。选项B错误。范围管理计划用于指导如下过程和相关工作：①制定项目范围说明书；②根据详细项目范围说明书创建WBS;③确定如何审批和维护范围基准；④正式验收已完成的项目可交付成果（P275）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q32" class="quiz-anchor"></a></p><p><strong>32.</strong> 在规划范围管理过程中，需要针对（ ）进行分析。</p><ul><li>A．工作绩效数据中记录的绩效指数</li><li>B．项目范围说明书中的范围基准</li><li>C．组织过程资产中的历史信息</li><li>D．风险登记册登记的风险清单</li></ul><details class="quiz" data-q="32" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：能够影响规划范围管理过程的组织过程资产主要包括：政策和程序、历史信息和经验教训知识库笠（P276）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q33" class="quiz-anchor"></a></p><p><strong>33.</strong> 规划范围管理过程的输出不包括（ ）。</p><ul><li>A．范围管理计划</li><li>B．质量管理计划</li><li>C．配置管理活动</li><li>D．需求管理计划</li></ul><details class="quiz" data-q="33" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：1.范围管理计划。范围管理计划是项目管理计划的组成部分，描述将如何定义、制定、监督、控制和确认项目范围。范围管理计划用于指导如下过程和相关工作：①制定项目范围说明书；②根据详细项目范围说明书创建WBS;③确定如何审批和维护范围基准；④正式验收已完成的项目可交付成果（P276）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q34" class="quiz-anchor"></a></p><p><strong>34.</strong> 规划范围管理过程的输入不包括（ ）。</p><ul><li>A．项目章程</li><li>B．开发方法</li><li>C．需求管理计划</li><li>D．质量管理计划</li></ul><details class="quiz" data-q="34" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：需求管理计划是规划范围管理过程的输出（P276）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q35" class="quiz-anchor"></a></p><p><strong>35.</strong> 关于需求的理解，不正确的是（ ）。</p><ul><li>A．让干系人积极参与需求的探索和分解工作，并仔细确定、记录和管理对产品、服务或成果的需求，能直接促进项目成功</li><li>B．为更好地对项目进行了解，收集需求的过程应在整个项目期间定期开展</li><li>C．需求是指根据特定协议或其他强制性规范，产品、服务或成果必须具备的条件或能力</li><li>D．需求包括发起人、客户和其他干系人的已量化且书面记录的需要和期望</li></ul><details class="quiz" data-q="35" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：收集需求：仅开展一次或仅在项目的预定义时开展（P276）　<span class="quiz-src">教材第 9 章章节习题</span></p></details><p><a id="q36" class="quiz-anchor"></a></p><p><strong>36.</strong> （ ）是把产品需求从其来源连接到能满足需求的可交付成果的一种表格。</p><ul><li>A．系统交互图</li><li>B．决策矩阵</li><li>C．需求跟踪矩阵</li><li>D．UC矩阵</li></ul><details class="quiz" data-q="36" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：孟求跟踪矩阵是把产品需求从其来源连接到能满足需求的可交付成果的二种表格（P281）　<span class="quiz-src">教材第 9 章章节习题</span></p></details><p><a id="q37" class="quiz-anchor"></a></p><p><strong>37.</strong> 关于收集需求过程及相关描述，正确的是（ ）。①收集需求是为实现目标而确定、记录并管理干系人的需要和需求的过程②收集需求过程需在整个项目期间持续开展，确保需求持续适配项目进展③该过程的作用是为定义产品范围和项目范围奠定基础④需求将作为后续WBS、成本、进度、质量和采购规划的基础⑤应该足够详细地挖掘、分析和记录需求，并将其作为范围基准</p><ul><li>A．①③④</li><li>B．①②④</li><li>C．②③⑤</li><li>D．①⑤</li></ul><details class="quiz" data-q="37" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：综上①③④表述正确（P276-277）　<span class="quiz-src">自编</span></p></details><p><a id="q38" class="quiz-anchor"></a></p><p><strong>38.</strong> 数据收集技术中，（ ）说法是错误的。</p><ul><li>A．焦点小组是召集预定的干系人和主题专家，了解他们对所讨论的产品、服务或成果的期望和态度。由一位受过训练的主持人引导大家进行互动式讨论</li><li>B．问卷调查是指设计一系列书面问题，向众多受访者快速收集信息</li><li>C．访谈是通过与干系人直接交谈，来获取信息的正式或非正式的方法。访谈的典型做法是向被访者提出预设和即兴的问题，并记录他们的回答</li><li>D．头脑风暴通过投票排列最有用的创意，以便进一步开展头脑风暴或优先排序</li></ul><details class="quiz" data-q="38" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：头脑风暴：是一种用来产生和收集对项目需求与产品需求的多种创意的技术（P278）　<span class="quiz-src">自编</span></p></details><p><a id="q39" class="quiz-anchor"></a></p><p><strong>39.</strong> （ ）将实际或计划的产品、过程和实践，与其他可比组织的实践进行比较，以便识别最佳实践，形成改进意见，并为绩效考核提供依据。</p><ul><li>A．头脑风暴</li><li>B．类比估算</li><li>C．问卷调查</li><li>D．标杆对照</li></ul><details class="quiz" data-q="39" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：标杆对照：将实际或计划的产品、过程和实践，与其他可比组织的实践进行比较，以便识别最佳实践，形成改进意见，并为绩效考核提供依据（P279）　<span class="quiz-src">自编</span></p></details><p><a id="q40" class="quiz-anchor"></a></p><p><strong>40.</strong> （ ）把从头脑风暴中获得的创意整合成一张图，用以反映创意之间的共性与差异，激发新创意</p><ul><li>A．亲和图</li><li>B．思维导图</li><li>C．文件分析</li><li>D．系统交互图</li></ul><details class="quiz" data-q="40" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：思维导图：把从头脑风暴中获得的创意整合成一张图，用以反映创意之间的共性与差异，激发新创意（P279）　<span class="quiz-src">自编</span></p></details><p><a id="q41" class="quiz-anchor"></a></p><p><strong>41.</strong> （ ）是用于促进头脑风暴的一种技术，通过投票排列最有用的创意，以便进一步开展头脑风暴或优先排序。</p><ul><li>A．名义小组技术</li><li>B．因果图</li><li>C．偏差分析</li><li>D．挣值分析</li></ul><details class="quiz" data-q="41" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：名义小组技术是用于促进头脑风暴的一种技术，通过投票排列最有用的创意，以便进一步开展头脑风暴或优先排序（P279）　<span class="quiz-src">自编</span></p></details><p><a id="q42" class="quiz-anchor"></a></p><p><strong>42.</strong> （ ）不是收集需求时数据收集的方法。</p><ul><li>A．头脑风暴</li><li>B．投票</li><li>C．焦点小组</li><li>D．标杆对照</li></ul><details class="quiz" data-q="42" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：收集需求的方法：1专家判断；2.数据收集（头脑风暴、访谈、焦点小组、问卷调查、标杆对照）;3数据分析（文件分析）;4.决策（投票、独裁型决策制定、多标准决策分析）;5数据表现（亲和图、思维导图）;6人际关系与团队技能（名义小组技术、观察和交谈、引导）7.系统交互图；8.原型、（P278-280）　<span class="quiz-src">自编</span></p></details><p><a id="q43" class="quiz-anchor"></a></p><p><strong>43.</strong> 以下属于功能需求的是（ ）。</p><ul><li>A．可辈性</li><li>B．安全性</li><li>C．流程</li><li>D．服务水平</li></ul><details class="quiz" data-q="43" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O。解决方案需求：为满足业务需求和干系人需求，产品、服务或成果必须具备的特性、功能和特征。解决方案需求又进一步分为功能需求和非功能需求：功能需求：描述产品应具备的功能，例如，产品应该执行的行动、流程、数据和交互；非功能需求；是对功能需求的补充，是产品正常运行所需的环境条件或质量要求，例如，可靠性、保密性、性能、安全性、服务水平、可支持性、保留或清除等（P28）　<span class="quiz-src">自编</span></p></details><p><a id="q44" class="quiz-anchor"></a></p><p><strong>44.</strong> 关于需求收集的描述，不正确的是（ ）。</p><ul><li>A．需求文件描述的是各单一需求如何满足项目的业务需求</li><li>B．作为基准的需求应该是明确的、可量化的、完整的和相互独立的</li><li>C．需求跟踪矩阵是一种表格，可以把每个需求与业务目标联系起来</li><li>D．测试策略和测试场景也是需求跟踪的内容</li></ul><details class="quiz" data-q="44" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O。需求文件描述各种单一需求将如何满足与项目相关的业务需求。一开始，可能只有高层级的需求，然后随着有关需求信息的增加而逐步细化（P28）　<span class="quiz-src">自编</span></p></details><p><a id="q45" class="quiz-anchor"></a></p><p><strong>45.</strong> 需求跟踪矩阵的作用是（ ）。</p><ul><li>A．可以体现需求与后续工作成果之间的对应关系</li><li>B．固化需求，防止变更</li><li>C．明确项目干系人对于需求的责任</li><li>D．对于需求复杂的项目，可以用来明确需求</li></ul><details class="quiz" data-q="45" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：需求跟踪矩阵是把产品需求从其来源连接到能满足需求的可交付成果的一种表格。使用盖求跟踪矩阵，把每个需求与业务目标或项目目标联系起来，有助于确保每个需求都具有业务价值需求跟踪矩阵提供了在整个项目生命周期中跟踪需求的一种方法，有助于确保需求文件中被批准的每项需求在项目结束的时候都能实现并交付（P281）　<span class="quiz-src">自编</span></p></details><p><a id="q46" class="quiz-anchor"></a></p><p><strong>46.</strong> （ ）不属于需求跟踪矩阵的内容。</p><ul><li>A．业务需要、机会、目的和目标</li><li>B．项目目标</li><li>C．测试策略和测试场景</li><li>D．项目的验收标准</li></ul><details class="quiz" data-q="46" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：跟踪需求的内容包括：①业务需要、机会、目的和目标；②项目目标；Q项目范围和WBS可交付成果；④产品设计；⑤产品开发；⑥测试策略和测试场最；⑦高层级需求到详细需求等（P281）　<span class="quiz-src">自编</span></p></details><p><a id="q47" class="quiz-anchor"></a></p><p><strong>47.</strong> 某软件项目实施过程中产生的一个文档的主要内容如下所示，该文档的主要作用是（ ）需求规格说明书 设计说明书 源代码库 测试用例库需求识别 v.o vi.o SDv.1 TCv12.1节 3.2节 MainFrame java 用例o1V1.1功能Boo? 6.2节 6.2节 用例ozvz.1EventJava功能BOo2</p><ul><li>A．工作分解</li><li>B．测试说明</li><li>C．需求跟踪</li><li>D．设计验证</li></ul><details class="quiz" data-q="47" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「需求跟踪」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q48" class="quiz-anchor"></a></p><p><strong>48.</strong> 表示需求和别的系统元素之间的联系链的最普遍方式是使用需求跟踪能力矩阵。如果软件开发人员发现，有一个孤立的设计元素在需求跟踪能力矩阵中不能回湖到需求，但其表明一个正当的功能，则说明（ ）。</p><ul><li>A．需求规格说明书漏掉了一项需求</li><li>B．设计元素不满足用户需求</li><li>C．需求规格不满足用户需求</li><li>D．在需求跟踪能力矩阵中不需要建立用户需求与设计元素之间的联系</li></ul><details class="quiz" data-q="48" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「需求规格说明书漏掉了一项需求」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q49" class="quiz-anchor"></a></p><p><strong>49.</strong> 在收集需求过程所使用的工具和技术中，（ ）是指在实际制造预期产品之前，先造出该产品的模型，并据此征求对需求的早期反馈。</p><ul><li>A．亲和图</li><li>B．思维导图</li><li>C．原型法</li><li>D．系统交互图</li></ul><details class="quiz" data-q="49" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O。原型法是指在实际制造预期产品之前，先造出该产品的模型，并据此征求对需求的早期反馈原型包括微缩产品、计算机生成的二维和三维模型、实体模型或模拟（P28）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q50" class="quiz-anchor"></a></p><p><strong>50.</strong> 一家银行决定开发一个新的金融风险管理软件，以满足监管机构金融交易监控新规，这属于（ ）</p><ul><li>A．系统需求</li><li>B．性能</li><li>C．业务</li><li>D．功能</li></ul><details class="quiz" data-q="50" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O。业务需求。整个组织的高层级需要，例如，解决业务问题或抓住业务机会，以及实施项目的原因（P28）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q51" class="quiz-anchor"></a></p><p><strong>51.</strong> （ ）是把产品需求从其来源连接到满足需求的可交付成果的一种表格结构。</p><ul><li>A．需求文件</li><li>B．项目范围说明书i</li><li>C．范围基准</li><li>D．需求跟踪矩阵</li></ul><details class="quiz" data-q="51" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：需求跟踪矩阵是把产品需求从其来源连接到能满足需求的可交付成果的一种表格。使用需求跟踪矩阵，把每个需求与业务目标或项目目标联系起来，有助于确保每个需求都具有业务价值需求跟踪矩阵提供了在整个项目生命周期中跟踪需求的一种方法，有助于确保需求文件中被批准的每项需求在项目结束的时候都能实现并交付（P281）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q52" class="quiz-anchor"></a></p><p><strong>52.</strong> 某项目只有项目发起人和两位技术高管掌握关键信息，需要单独向相关干系人收集需求。最适合的数据收集技术是（ ）。</p><ul><li>A．头脑风暴</li><li>B．访谈</li><li>C．焦点小组</li><li>D．标杆对照</li></ul><details class="quiz" data-q="52" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：可用于收集需求过程的数据收集技术主要包括头脑风暴、访谈、焦点小组、问卷调查和标杆对照等。(1)头脑风暴。头脑风暴是一种用来产生和收集对项目需求与产品需求的多种创意的技术“(2)边谈（P278-279）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q53" class="quiz-anchor"></a></p><p><strong>53.</strong> （ ）是收集需求的输出。</p><ul><li>A．项目管理计划</li><li>B．立项管理文件</li><li>C．需求跟踪矩阵</li><li>D．组织过程资产</li></ul><details class="quiz" data-q="53" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：280-281。收集需求过程的主要输出为需求文件和需求跟踪矩阵　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q54" class="quiz-anchor"></a></p><p><strong>54.</strong> 在范围管理规划阶段，用来对大量创意进行分组的技术是（ ）。</p><ul><li>A．亲和图</li><li>B．思维导图</li><li>C．系统交互图</li><li>D．原型法</li></ul><details class="quiz" data-q="54" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：亲和图：用来对大量创意进行分组的技术，以便进一步审查和分析（P279）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q55" class="quiz-anchor"></a></p><p><strong>55.</strong> 在需求文件中，（ ）的需求可作为基准使用。①可测量和可测试；②项目经理认可；③完整且可跟踪；④相对独立无依赖</p><ul><li>A．①②</li><li>B．①③</li><li>C．③④</li><li>D．②③</li></ul><details class="quiz" data-q="55" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O。只有明确的（可测量和可测试的）、可跟踪的、完整的、相互协调的，且主要干系人愿意认可的需求，才能作为基准（P28）　<span class="quiz-src">2022 年上半年高项</span></p></details><p><a id="q56" class="quiz-anchor"></a></p><p><strong>56.</strong> （ ）用于确认项目可交付成果的成功完成或其他项目需求的实现的任何条件或标准</p><ul><li>A．业务需求</li><li>B．解决方案需求</li><li>C．质量需求</li><li>D．过渡与就绪需求</li></ul><details class="quiz" data-q="56" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：质量需求：用于确认项目可交付成果的成功完成或其他项目需求的实现的任何条件或标准，例如，测试、认证、确认等（P281）　<span class="quiz-src">2023 年上高项</span></p></details><p><a id="q57" class="quiz-anchor"></a></p><p><strong>57.</strong> 关于收集需求管理过程及相关技术的描述，正确的是（ ）。</p><ul><li>A．需求跟踪矩阵是把产品需求从其来源连接到能满足需求的可交付成果的一种表格</li><li>B．原型法是一种结构化的头脑风暴形式，通过投票排列最有用的创意</li><li>C．故事板是一种原型技术，是对产品范围的可视化描绘，可以直观显示业务系统的交互方式</li><li>D．收集需求管理过程为规划范围管理过程英定基础，需要反复开展，贯穿于整个项目生命周期</li></ul><details class="quiz" data-q="57" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：P280。原型法：在实际制造预期产品之前，先造出该产品的模型。原型包括微缩产品、计算机生成的二维和三维模型、实体模型或模拟（P276-280）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q58" class="quiz-anchor"></a></p><p><strong>58.</strong> 关于收集需求的描述，不正确的是（ ）。</p><ul><li>A．需求包括发起人和其他干系人的已量化且书面记录的需要和期望</li><li>B．让干系人积极参与需求的探索和分解工作，并仔细确定、记录和管理对产品、服务或成果的需求，能直接促进项目成功</li><li>C．应该足够详细地挖拥、分析和记录需求，并将其作为范围基准</li><li>D．需求是指根据特定协议或其他强制性规范，产品、服务或成果必须具备的条件或能力</li></ul><details class="quiz" data-q="58" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：收集到的需求还需要经过整理、评审后才能包含在范围基准内　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q59" class="quiz-anchor"></a></p><p><strong>59.</strong> 适用于“收集需求”过程的决策技术，不包括（ ）。</p><ul><li>A．思维导图</li><li>B．多标准决策分析</li><li>C．独越型决策制定</li><li>D．投票</li></ul><details class="quiz" data-q="59" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：思维导图):属于收集需求过程的数据表现技术，用于将头脑风基获得的创意整合成图以反映共性与差异，不属于决策技术　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q60" class="quiz-anchor"></a></p><p><strong>60.</strong> 应根据（ ）来编制详细的项目范围说明书。①可交付成果；②假设条件；③制约因素；④WBS</p><ul><li>A．①②③</li><li>B．①②④</li><li>C．①③④</li><li>D．②③④</li></ul><details class="quiz" data-q="60" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：应根据项目启动过程中记载的主要可交付成果、假设条件和制约因素来编制详细的项目范围说明书。在项目范围说明书定义前，还没有WBS，所以BCD错误（P282）　<span class="quiz-src">教材第 9 章章节习题</span></p></details><p><a id="q61" class="quiz-anchor"></a></p><p><strong>61.</strong> 关于项目范围说明书的理解，不正确的是（ ）。</p><ul><li>A．项目范围说明书可明确指出哪些工作不属于本项目范围</li><li>B．项目范围说明书使项目团队能进行更详细的规划，并为评价变更请求或额外工作是否超过项目边界提供基准</li><li>C．项目范围说明书描述要做和不要做的工作的详细程度，决定着项目管理团队控制整个项目范围的有效程度</li><li>D．项目范围说明书不能代表项目干系人之间就项目范围所达成的共识</li></ul><details class="quiz" data-q="61" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目范围说明书是对项目范围、主要可交付成果、假设条件和制约因素的描述。它记录了整个范围，包括：项目和产品范围；详细描述了项目的可交付成果；代表项目王系人之间就项目范围所达成的共识（P283-284）　<span class="quiz-src">教材第 9 章章节习题</span></p></details><p><a id="q62" class="quiz-anchor"></a></p><p><strong>62.</strong> 关于项目范围定义的描述，不正确的是（ ）。</p><ul><li>A．范围定义是制定项目和产品详细描述的过程</li><li>B．范围定义过程的输出包括范围管理计划、干系人登记册、需求文件</li><li>C．范围说明书是对项目范围、可交付成果、假设条件和制约因素等的描述</li><li>D．项目进行中，往往需要多次反复开展范围定义的活动</li></ul><details class="quiz" data-q="62" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：范围管理计划是规划范围管理的输出，干系人登记册是识别干系人的输出，需求文件是收集需求的输出，B是完全错误（P282）　<span class="quiz-src">自编</span></p></details><p><a id="q63" class="quiz-anchor"></a></p><p><strong>63.</strong> 可作为定义范围过程输入的项目文件包括假设日志、需求文件和（ ），其中（ ）包含了可能影响项目范围的应对策略，（ ）识别了应纳入范围的需求。</p><ul><li>A．风险登记册、风险登记册、需求文件</li><li>B．项目范围说明书、风险登记册、需求文件</li><li>C．风险登记册、需求文件、假设日志</li><li>D．项目范围说明书、需求文件、风险登记册</li></ul><details class="quiz" data-q="63" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：定义范围的输入包括假设日志、需求文件和风险登记册。其中风险登记册包含了可能影响项目范围的应对策略；需求文件识别了应纳入范围的需求；假设日志识别了有关产品、项目、环境、干系人以及会影响项目和产品范围的假设条件和制约因素（P282）　<span class="quiz-src">自编</span></p></details><p><a id="q64" class="quiz-anchor"></a></p><p><strong>64.</strong> 在范围定义的工具和技术中，（ ）通过产品分解、系统分析、价值工程等技术理清产品范围并把对产品的要求转化成项目的要求。</p><ul><li>A．焦点小组</li><li>B．备选方案生成</li><li>C．产品分析</li><li>D．引导式研讨会</li></ul><details class="quiz" data-q="64" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：产品分析可用于定义产品和服务，包括针对产品或服务提问并回答，以描述要交付产品的用途、特征及其他方面。产品分析技术主要包括：产品分解、需求分析、系统分析、系统工程、价值分析、价值工程等（P283）　<span class="quiz-src">自编</span></p></details><p><a id="q65" class="quiz-anchor"></a></p><p><strong>65.</strong> 某项目经理张先生在确定项目范围过程中，已得到项目章程、工作说明书、企业环境因素和组织过程资产等信息，他立刻组织项目团队管理人员，并聘请有关专家，采用项目管理信息系统、项目管理方法论等工具，确定项目需要完成的工作，在上述工作结束后，相应的输出是（ ）</p><ul><li>A．项目进度计划</li><li>B．项目范围说明书</li><li>C．工作绩效报告</li><li>D．项目审计报告</li></ul><details class="quiz" data-q="65" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：283。张先生在确定项目范围过程中，说明就是定义范围过程。而定义范围的输出是项目范围说明书　<span class="quiz-src">自编</span></p></details><p><a id="q66" class="quiz-anchor"></a></p><p><strong>66.</strong> 项目经理向干系人说明项目范围时，应以（ ）为依据。</p><ul><li>A．合同</li><li>B．项目范围说明书</li><li>C．WBS</li><li>D．产品说明书</li></ul><details class="quiz" data-q="66" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目范围说明书是对项目范围、主要可交付成果、假设条件和制约因素的描述。它记录了整个范围，包括：项目和产品范围；详细描述了项目的可交付成果；代表项目干系人之间就项目范围所达成的共识（P283）　<span class="quiz-src">自编</span></p></details><p><a id="q67" class="quiz-anchor"></a></p><p><strong>67.</strong> （ ）描述了项目可交付成果和产生这些可交付成果所必须做的项目工作，就此在所有项目干系人之间建立了共识。</p><ul><li>A．SOW</li><li>B．配置管理计划</li><li>C．范围说明书</li><li>D．工作分解结构</li></ul><details class="quiz" data-q="67" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目范围说明书是对项目范围、主要可交付成果、假设条件和制约因素的描述。它记录了整个范围，包括：项目和产品范围；详细描述了项目的可交付成果；代表项目干系人之间就项目范围所达成的共迟（P283-284）　<span class="quiz-src">自编</span></p></details><p><a id="q68" class="quiz-anchor"></a></p><p><strong>68.</strong> 详细的项目范围说明书不包括（ ）。</p><ul><li>A．产品范围描述</li><li>B．可交付成果</li><li>C．WBS</li><li>D．项目的除外责任</li></ul><details class="quiz" data-q="68" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：详细的项目范围说明书包括内容有：■产品范围描述：项目章程和需求文件中所述的产品、服务或成果特征。■可交付成果：为完成某一过程、阶段或项目而必须产出的任何独特并可核实的产品、成果或服务能力，可交付成果也包括各种辅助成果，如项目管理报告和文件（P284）　<span class="quiz-src">自编</span></p></details><p><a id="q69" class="quiz-anchor"></a></p><p><strong>69.</strong> （ ）不属于项目范围说明书的内容。</p><ul><li>A．批准的项目原因</li><li>B．项目验收标准</li><li>C．项目可交付成果</li><li>D．产品范围描述</li></ul><details class="quiz" data-q="69" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：详细的项目范围说明书内容有：产品范围描述、可交付成果、验收标准、项目的除外责任（P284）　<span class="quiz-src">自编</span></p></details><p><a id="q70" class="quiz-anchor"></a></p><p><strong>70.</strong> （ ）为完成某一过程、阶段或项目而必须产出的任何独特并可核实的产品、成果或服务能力，其也包括各种辅助成果，如项目管理报告和文件。</p><ul><li>A．产品范围描述</li><li>B．可交付成果</li><li>C．验收标准</li><li>D．项目的除外责任</li></ul><details class="quiz" data-q="70" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：可交付成黑：为完成某一过程、阶段或项目而必须产出的任何独特并可核实的产品、成果或服务能力，可交付成果也包括各种辅助成果，如项目管理报告和文件（P284）　<span class="quiz-src">自编</span></p></details><p><a id="q71" class="quiz-anchor"></a></p><p><strong>71.</strong> 以下说法不正确的是（ ）。</p><ul><li>A．项目章程和项目范围说明书的内容存在一定程度的重叠</li><li>B．项目章程包含高层级的信息，而项目范围说明书则是对范围组成部分的详细描述</li><li>C．由于在收集需求过程中识别出的所有需求未必都包含在项目中，所以定义范围过程需要从需求文件中选取最终的项目需求，然后制定出关于项目及其产品、服务或成果的详细描述</li><li>D．项目章程的内容和项目范围说明书的内容存在冲突时，应以项目章程为主</li></ul><details class="quiz" data-q="71" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：虽然项目章程和项目范围说明书的内容存在一定程度的重叠，但它们的详细程度完全不同项目章程包含高层级的信息，而项目范围说朗书则是对范围组成部分的详细描述，这些组成部分需要在项目过程中渐进明细（P284）　<span class="quiz-src">自编</span></p></details><p><a id="q72" class="quiz-anchor"></a></p><p><strong>72.</strong> 在范围管理里，可用作定义范围过程输入的项目文件是（ ）。</p><ul><li>A．风险登记册</li><li>B．范围基准</li><li>C．产品范围</li><li>D．WBS</li></ul><details class="quiz" data-q="72" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：可作为定义范围过程输入的项目文件主要包括：●假设日志：识别了有关产品、项目、环境、干系人以及会影响项目和产品范围的假设条件和制约因素（P282）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q73" class="quiz-anchor"></a></p><p><strong>73.</strong> 在定义范围过程中，明确记录哪些工作不属于项目范围是为了（ ）</p><ul><li>A．为创建工作分解结构(WBS)提供明确的输入依据</li><li>B．管理干系人期望，减少项目范围蔓延</li><li>C．作为后续变更请求中评估变更影响的基准</li><li>D．明确项目验收时需要交付的其体成果清单</li></ul><details class="quiz" data-q="73" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目的除外责任。识别排除在项目之外的内容。明确说明哪些内容不画于项目范用，有助于管理干系人的期望及减少范用蔓延（P284）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q74" class="quiz-anchor"></a></p><p><strong>74.</strong> 定义范围的输入不包括（ ）。</p><ul><li>A．假设日志</li><li>B．需求文件</li><li>C．WBS字典</li><li>D．风险登记册</li></ul><details class="quiz" data-q="74" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：可用作定义范围过程输入的项目文件主要包括假设日志、需求文件和风险登记册等（P282）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q75" class="quiz-anchor"></a></p><p><strong>75.</strong> 范围基准是项目管理计划的组成部分，其中（ ）是定义范围的输出。</p><ul><li>A．工作包</li><li>B．范围说明书</li><li>C．WBS</li><li>D．WBS字典</li></ul><details class="quiz" data-q="75" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：288-289。范围基准是项目管理计划的组成部分，包括项目范围说明书、WBS工作包、规划包和 WBS字典等。P283-284　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q76" class="quiz-anchor"></a></p><p><strong>76.</strong> 定义范围最重要的任务就是详细定义项目的范围边界，（ ）不适合用于描述某个项目的范围。</p><ul><li>A．系统开发完成后，开发人员针对系统操作为客户举行两次以上的培训</li><li>B．服务软件在对外传输数据过程中不允许以明文形式传输</li><li>C．将主会场原有的标清视频会议系统替换为高清(1080P)视频会议系统</li><li>D．智能数据分析系统核心功能在2个月内完成，以满足验收要求</li></ul><details class="quiz" data-q="76" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「智能数据分析系统核心功能在2个月内完成，以满足验收要求」，原解析未给课本依据　<span class="quiz-src">2022 年下半年高项</span></p></details><p><a id="q77" class="quiz-anchor"></a></p><p><strong>77.</strong> 项目范围说明书包括的内容有（ ）。①产品范围描述；②需求跟踪矩阵；③项目除外责任；④干系人登记册；⑤可交付成果；⑥验收标准</p><ul><li>A．①②④⑥</li><li>B．①③⑤⑥</li><li>C．①②③⑤</li><li>D．①②⑤⑥</li></ul><details class="quiz" data-q="77" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目范围说明书描述要做和不要做的工作的详细程度，决定着项目管理团队控制整个项目范围的有效程度。详细的项目范围说明书包括内容有：【口诀：产教研外】产品范围描述：项目章程和需求文件中所述的产品、服务或成果特征◆可交付成墨：为完成某一过程、阶段或项目而必须产出的任何独特并可核实的产品、成果或服务能力，可交付成果也包括各种辅助成果，如项目管理报告和文件（P284）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q78" class="quiz-anchor"></a></p><p><strong>78.</strong> 关于项目范围说明书的描述，不正确的是（ ）。</p><ul><li>A．项目范围说明书应该与项目章程详细程度完全不同，内容不可重叠</li><li>B．项目验收的标准也应该记录在项目范围说明书中</li><li>C．项目范围说明书应该准确地描述要做和不要做的工作</li><li>D．项目范围说明书是对项目范围、主要可交付成果、假设条件和制约因素的描述</li></ul><details class="quiz" data-q="78" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：量然项目章程和项目范围说明书的内容存在一定程度的重叠，但它们的详细程度完全不同项目章程包含高层级的信息，而项目范围说明书则是对范围组成部分的详细描述，这些组成部分需要在项目过程中渐进明细（P284）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q79" class="quiz-anchor"></a></p><p><strong>79.</strong> 下列不属于定义范围过程应用的工具与技术的是（ ）。</p><ul><li>A．分解</li><li>B．专家判断</li><li>C．备选方案分析</li><li>D．决策</li></ul><details class="quiz" data-q="79" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：BCD都是定义范围过程的工具和技术，A不正确，A分解属于创建WBS的工具和技术9.6 创建 WBS(P284-289)（P283）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q80" class="quiz-anchor"></a></p><p><strong>80.</strong> 范围基准包括（ ）。①经过批准的范围说明书；②项目章程；③WBS词典；④WBS;⑤项目管理计划</p><ul><li>A．①②⑤</li><li>B．①2④</li><li>C．①③④</li><li>D．①④⑤</li></ul><details class="quiz" data-q="80" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：范围基准是经过批准的范围说明书、WBS和相应的WBS词典，只有通过正式的变更控制程序才能进行变更，它被用作比较的基础。范围基准是项目管理计划的组成部分（P288）　<span class="quiz-src">教材第 9 章章节习题</span></p></details><p><a id="q81" class="quiz-anchor"></a></p><p><strong>81.</strong> 把项目可交付成果和项目工作分解成较小、更易于管理的组件的过程是（ ）</p><ul><li>A．创建工作分解结构</li><li>B．收集需求</li><li>C．确认范田</li><li>D．范田控制</li></ul><details class="quiz" data-q="81" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：创建工作分解结构(WBS)是把项目可交付成果和项目工作分解成较小、更易于管理的组件的过程。本过程的主要作用是为所要交付的内容提供架构（P284）　<span class="quiz-src">自编</span></p></details><p><a id="q82" class="quiz-anchor"></a></p><p><strong>82.</strong> 关于创建WBS过程及相关描述，正确的是（ ）。①创建WBS是把项目可交付成果和项目工作分解成较小、更易于管理的组件的过程，其作用是为所要交付的内容提供架构②创建WBS过程需要在整个项目期间反复开展，确保分解结果持续适配项目进展③WBS最低层的组成部分称为工作包，可对其成本和持续时间进行估算和管理④WBS组织并定义了项目的总范围，代表着经批准的当前项目范围说明书中所规定的工作“⑤WBS中的“工作”指的是活动本身，而非作为活动结果的工作产品或可交付成果</p><ul><li>A．①③④</li><li>B．①②④</li><li>C．②③⑤</li><li>D．①③⑤</li></ul><details class="quiz" data-q="82" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：综上①③④表述正确（P284-285）　<span class="quiz-src">自编</span></p></details><p><a id="q83" class="quiz-anchor"></a></p><p><strong>83.</strong> 要把整个项目工作分解为工作包，通常需要开展如下活动：①识别和分析可交付成果及相关工作；②（ ）；③自上而下逐层细化分解；④为 WBS 组成部分制定和分配标识编码；⑤核实可交付成果分解的程度是否恰当。</p><ul><li>A．确定 WBS 的结构和编排方法</li><li>B．收集需求</li><li>C．指定责任人</li><li>D．范围定义</li></ul><details class="quiz" data-q="83" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：要把整个项目工作分解为工作包，通常需要开展如下活动：①识别和分析可交付成果及相关工作；②确定WBS的结构和编排方法；③自上面下逐层细化分解；④为WBS组成部分制定和分配标识编码；⑤核实可交付成果分解的程度是否恰当（P285-286）　<span class="quiz-src">自编</span></p></details><p><a id="q84" class="quiz-anchor"></a></p><p><strong>84.</strong> 关于WBS描述正确的是（ ）。</p><ul><li>A．WBS分解得越详细越利于项目的执行</li><li>B．WBS的元素可以几个人同时负责</li><li>C．WBS完成后，就不能对WBS进行修改</li><li>D．WBS中下级元素之和等于上级元素</li></ul><details class="quiz" data-q="84" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：A错误。WBS分解得越详细越利于项目的执行（过细的分解公造成管理努力的无效耗费、资源使用效率低下、工作实施效率降低，同时造成WBS各层级的数据江总困难）B错误（P287-288）　<span class="quiz-src">自编</span></p></details><p><a id="q85" class="quiz-anchor"></a></p><p><strong>85.</strong> 在创建WBS的过程中，以下说法错误的是（ ）。</p><ul><li>A．100%原则（包含原则）认为，在WBS中，所有下一级的元素之和必须100%代表上一级的元素</li><li>B．WBS的底层不但要支持项目管理计划，而且要让管理层能够监视和控制项目的进度和预算</li><li>C．WBS中的元素必须有人负责，而且只有一个人负责</li><li>D．分包出去的工作的WBS不需要包含在整个项目中</li></ul><details class="quiz" data-q="85" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：WBS应包括项目管理工作（因为管理是项目具体工作的一部分），也要包括分包出去的工作（P288）　<span class="quiz-src">自编</span></p></details><p><a id="q86" class="quiz-anchor"></a></p><p><strong>86.</strong> 关于工作分解结构(WBS)的描述，不正确的是（ ）</p><ul><li>A．WBS最底层的工作单元称为工作包</li><li>B．工作分解结构的编制不需要客户参与</li><li>C．每个工作要素相互独立，尽量减少交叉</li><li>D．下一级所有元素之和必须100%代表上一级元素</li></ul><details class="quiz" data-q="86" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：WBS的编制需要所有（主要）项目干系人的参与。所以B错误（P288）　<span class="quiz-src">自编</span></p></details><p><a id="q87" class="quiz-anchor"></a></p><p><strong>87.</strong> 在WBS字典中，可不包括的是（ ）。</p><ul><li>A．工作概述</li><li>B．账户编码</li><li>C．管理储备</li><li>D．资源需求</li></ul><details class="quiz" data-q="87" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：WBS词典可能包括账户编码标识、工作描述、假设条件和制约因素、负责人或组织单元进度里程碘、相关的进度活动、所需资源、成本估算、质量要求、验收标准、技术参考文献、协议信息等（P289）　<span class="quiz-src">自编</span></p></details><p><a id="q88" class="quiz-anchor"></a></p><p><strong>88.</strong> 某待开发的信息系统工作分解结构图如下图所示，其中标有序号的方框应该填写的内容是（ ）。原题附图（略）：一张信息系统 WBS 分解图，第二层按阶段划分，图中以序号标示待填写的方框。</p><ul><li>A．同行评审</li><li>B．计划评审</li><li>C．项目管理计划制定</li><li>D．集成方案制定</li></ul><details class="quiz" data-q="88" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「项目管理计划制定」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q89" class="quiz-anchor"></a></p><p><strong>89.</strong> 按照下图所示的项目分解结构，其中空白处的内容应为（ ）。原题附图（略）：项目分解结构图，按需求、设计、集成准备、集成实施、测试与验收等阶段展开，图中以空白框标示待填内容。</p><ul><li>A．需求开发、系统测试</li><li>B．需求开发、系统交付</li><li>C．需求确认、系统测试</li><li>D．需求确认、系统交付</li></ul><details class="quiz" data-q="89" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「需求确认、系统测试」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q90" class="quiz-anchor"></a></p><p><strong>90.</strong> 高洋作为一个大项目的项目经理，最近将其中一个子项目分派给了一个分包商，李华是分包商的项目经理，刚刚从事项目管理工作，但是与王工比较熟悉。王工可建议李华首先（ ）</p><ul><li>A．遵照王工为项目制定的WBS，直接使用王工确定的工作包来管理子项目</li><li>B．制定该子项目的WBS</li><li>C．建立类似的编码结构，以便于应用公共项目管理信息系统</li><li>D．建立一个WBS词典来显示详细的人员分工</li></ul><details class="quiz" data-q="90" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「制定该子项目的WBS」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q91" class="quiz-anchor"></a></p><p><strong>91.</strong> （ ）通常不是创建工作分解结构(WBS)的直接输入。</p><ul><li>A．需求文件</li><li>B．项目章程</li><li>C．项目范围说明书</li><li>D．范围管理计划</li></ul><details class="quiz" data-q="91" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：创建WBS过程中使用的项目管理计划组件是范围管理计划。可用作创建WBS过程输入的项目文件主要包括项目范围说明书和需求文件等（P285）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q92" class="quiz-anchor"></a></p><p><strong>92.</strong> （ ）可以包含一个或多个规划包。</p><ul><li>A．工作包</li><li>B．WBS字典</li><li>C．项目范围说明书</li><li>D．控制账户</li></ul><details class="quiz" data-q="92" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：规划包是一种低于控制账户而高于工作包的工作分解结构组件，工作内容已知，但详细的进度活动未知，二个控制账户可以包含一个或多个规划包（P289）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q93" class="quiz-anchor"></a></p><p><strong>93.</strong> （ ）是一种低于控制账户而高于工作包的工作分解结构组件，工作内容已知，但详细的进度活动未知。</p><ul><li>A．规划包</li><li>B．控制账户</li><li>C．活动</li><li>D．WBS字典</li></ul><details class="quiz" data-q="93" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：289。规划包是一种低于控制账户面高于工作包的工作分解结构组件，工作内容已知，但详细的进度活动未知，一个控制账户可以包含一个或多个规划包　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q94" class="quiz-anchor"></a></p><p><strong>94.</strong> 以下WBS注意事项中错误的是（ ）。</p><ul><li>A．WBS的一个工作单元可以从属多个上层单元，以便工作的交接</li><li>B．WBS必须是面向可交付成果的</li><li>C．WBS的底层应该支持计划和控制</li><li>D．WBS并非一成不变的</li></ul><details class="quiz" data-q="94" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：在分解的过程中，应该注意以下8个方面<em>(1)WBS必须是面向可交付成果的。</em>(2)WBS必须符合项目的范围。*(3)WBS的底层应该支持计划和控制（P287-288）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q95" class="quiz-anchor"></a></p><p><strong>95.</strong> 某公司中标一个企业信息化系统开发项目，合同中该项目包括人事系统、OA 系统和生产系统。下图为项目经理制作的 WBS，此处项目经理违反了关于 WBS 的（ ）原则。原题附图（略）：WBS 第一层按人事系统、OA 系统、生产系统划分，其下再按功能模块继续分解。</p><ul><li>A．WBS 需要考虑将不同的人员的工作分开</li><li>B．WBS 中各项工作是为提供可交付成果服务的</li><li>C．可以按照系统子系统来逐层分解 WBS</li><li>D．一个工作单元只能从属于某个上层单元</li></ul><details class="quiz" data-q="95" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：图片里员工培训既属于系统又属于人事系统，违背“一个工作单元只能从属于某个上层单元，避免交义从属。”（P288）　<span class="quiz-src">2017 年下半年高项</span></p></details><p><a id="q96" class="quiz-anchor"></a></p><p><strong>96.</strong> 关于WBS的描述，不正确的是（ ）。</p><ul><li>A．WBS必须且只能包括10O%的工作</li><li>B．WBS的元素必须指定一个或多个负责人</li><li>C．WBS应该由全体项目成员、用户和项目干系人一致确认</li><li>D．分包出去的工作也应纳入WBS中</li></ul><details class="quiz" data-q="96" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：WBS分解注意事项：1、WBS 必须是面向可交付成果的；“2、WBS必须符合项目的范围，WBS必须包括，也仅包括为了完成项目的可交付成果的活动（P287-288）　<span class="quiz-src">2018 年上半年高项</span></p></details><p><a id="q97" class="quiz-anchor"></a></p><p><strong>97.</strong> 某公司决定在现有公文处理系统的基础上，新开发一个移动端APP，便于大家远程办公。项目经理召开工作会议，就工作分解结构提出了如下的建议，其中（ ）是不妥当的。</p><ul><li>A．项目组所有人员都要参与，任务分解的层次控制在4至6层之间</li><li>B．对目前尚不清楚具体活动的模块可以使用规划包进行分解</li><li>C．项目干系人对完成的WBS给予确认，并达成共识</li><li>D．项目经理负责项目WBS分解，外包商负责外包合同WBS的分解</li></ul><details class="quiz" data-q="97" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：D错误。WBS应包括项目管理工作（因为管理是项目具体工作的一部分），也要包括分包出去的工作（P287-288）　<span class="quiz-src">2018 年下半年高项</span></p></details><p><a id="q98" class="quiz-anchor"></a></p><p><strong>98.</strong> 关于工作分解结构(WBS)的描述，正确的是（ ）。</p><ul><li>A．WBS必须符合项目范围</li><li>B．WBS元素必须由多个人负责</li><li>C．WBS必须控制在5-8层</li><li>D．WBS的编制只需要项目团队成员参与</li></ul><details class="quiz" data-q="98" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A正确。B错误。WBS中的元素必须有人负责，而且只由一个人负责。C错误。WBS可以控制在4-6层，不是必需，更不是5-8层（P287-288）　<span class="quiz-src">2019 年上半年高项</span></p></details><p><a id="q99" class="quiz-anchor"></a></p><p><strong>99.</strong> 关于WBS的描述，正确的是（ ）。</p><ul><li>A．WBS中的各项工作为可交付成果提供服务</li><li>B．WBS的内容一般会超出完成可交付成果的活动范围</li><li>C．WBS中的元素可以由一人或多人负责</li><li>D．WBS应包括分包的工作，但不包括管理工作</li></ul><details class="quiz" data-q="99" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：WBS分解注意事项：1、WBS必须是面向可交付成果的；“2、WBS必须符合项目的范围，WBS必须包括，也仅包括为了完成项目的可交付成果的活动（P287-288）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q100" class="quiz-anchor"></a></p><p><strong>100.</strong> 某公司承接了一个医疗集团系统升级的项目，涉及多家医疗机构。项目经理在创建WBS时，发现各家医疗机构对系统功能需求差异较大，且个别医疗机构的部分需求尚未明确。最适合当前情况的WBS分解方式是（ ）。</p><ul><li>A．按项目生命周期阶段分解，每个阶段下再按医疗机构划分</li><li>B．采用滚动式规划，先分解已知需求，后续逐步细化未知部分</li><li>C．按主要可交付成果分解，每个成果下再按功能模块细分</li><li>D．采用自上而下逐层细化，先按医疗机构分解，再在每个医疗机构下细化功能模块</li></ul><details class="quiz" data-q="100" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「采用滚动式规划，先分解已知需求，后续逐步细化未知部分」，原解析未给课本依据　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q101" class="quiz-anchor"></a></p><p><strong>101.</strong> 关于WBS分解过程的描述，正确的是（ ）。</p><ul><li>A．完成WBS之后，为了保持需求稳定尽量不对其进行修改</li><li>B．一个工作单元可以从属于多个上层单元</li><li>C．WBS的编制不需要所有项目干系人的参与，只需要部分干系人参与</li><li>D．WBS中的元素必须有人负责，而且只有一个人负责</li></ul><details class="quiz" data-q="101" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：WBS中的元素必须有人负责，而且只有一个人负责，这个规定又称为独立责任原则（P288）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q102" class="quiz-anchor"></a></p><p><strong>102.</strong> 关于项目范围确认及有关活动，以下说法错误的是（ ）。</p><ul><li>A．可以通过检查来实现范围的确认</li><li>B．检查包括测量、审查与确认等活动</li><li>C．范围确认的目的就是形成项目范围说明书</li><li>D．检查也可被称为审查、产品评审和走查</li></ul><details class="quiz" data-q="102" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：确认范围是正式验收已完成的项目可交付成果的过程。本过程的主要作用：①使验收过程具有客观性；②通过确认每个可交付成果来提高最终产品、服务或成果获得验收的可能性C错误（P289）　<span class="quiz-src">自编</span></p></details><p><a id="q103" class="quiz-anchor"></a></p><p><strong>103.</strong> 关于确认范围和质量控制的描述，不正确的是（ ）。</p><ul><li>A．确认范围关注可交付成果的验收</li><li>B．质量控制关注可交付成果的正确性及是否满足质量要求</li><li>C．确认范围和质量控制均由组织内部质量部门实施</li><li>D．确认范围和质量控制都可以通过检查的方法来进行</li></ul><details class="quiz" data-q="103" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：确认范围过程与控制质量过程的不同之处在于，前者关注可交付成果的验收，而后者关注可交付成果的正确性及是否满足质量要求。控制质量过程通管先于确认范围过程，但二者也可同时进位（P290）　<span class="quiz-src">自编</span></p></details><p><a id="q104" class="quiz-anchor"></a></p><p><strong>104.</strong> 进行范围确认是项目管理中一项非常重要的工作，制定和执行确认程序时，第一项工作一般是（ ）。</p><ul><li>A．确定需要进行确认范围的时间</li><li>B．识别确认范围需要哪些投入</li><li>C．确定确认范围正式被接受的标准和要素</li><li>D．确定确认范围会议的组织步骤</li></ul><details class="quiz" data-q="104" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：确认范围的一般步骤：①确定需要进行确认范围的时间；②识别确认范围需要哪些投入；③确定范围正式被接受的标准和要素；④确定确认范围会议的组织步骤；⑤组织确认范围会议（P290）　<span class="quiz-src">自编</span></p></details><p><a id="q105" class="quiz-anchor"></a></p><p><strong>105.</strong> 确认范围的步骤包括以下内容，正确的执行顺序是（ ）。①确定范围正式被接受的标准和要素；“②确定需要进行确认范围的时间；③组织确认范围公议；④确定确认范围会议的组织步骤；⑤识别确认范围需要哪些投入</p><ul><li>A．②⑤①④③</li><li>B．①②④⑤③</li><li>C．②①⑤④③</li><li>D．5②④①③</li></ul><details class="quiz" data-q="105" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：确认范围的一般步骤：①确定需要进行确认范围的时间；②识别确认范围需要哪些投入；③确定范围正式被接受的标准和要素；④确定确认范围公议的组织步骤；⑤组组确认范围公议（P290）　<span class="quiz-src">自编</span></p></details><p><a id="q106" class="quiz-anchor"></a></p><p><strong>106.</strong> 以下关于范围管理的说法中，不正确的是（ ）。</p><ul><li>A．标杆对照所采用的可比组织可以是内部的，也可以是外部的</li><li>B．WBS最低层的组成部分称为工作包，包括计划的工作</li><li>C．范围基准是经过批准的范围说明书、WBS和相应的WBS词典，范围基准是项目管理计划的组成部分</li><li>D．高层管理主要关注项目可交付成果是否足够和必须完成，时间、资金和资源是否足够</li></ul><details class="quiz" data-q="106" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理层主要关注项目范围：是指范围对项目的进度、资金和资源的影响，这些因素是否超过了组织承受范用，是否在投入产出上具有合理性（P290-291）　<span class="quiz-src">自编</span></p></details><p><a id="q107" class="quiz-anchor"></a></p><p><strong>107.</strong> 项目范围说明书、工作分解结构、范围管理计划和可交付成果都是范围确认的（ ）</p><ul><li>A．工具</li><li>B．技术</li><li>C．成果</li><li>D．输入</li></ul><details class="quiz" data-q="107" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：范围确认的输入：1项目管理计划（范围管理计划、需求管理计划、范围基准）;2.项目文件（需求文件、蛋求跟紧矩阵、质量报告、经验教训登记册）;3工作绩效数据；4.核实的可交位成果项目范围说明书、工作分解结构、项目范围管理计划这种一看就属于文件类的东西，要么是输入要么是输出，肯定不是工其和技术（P291）　<span class="quiz-src">自编</span></p></details><p><a id="q108" class="quiz-anchor"></a></p><p><strong>108.</strong> 关于确认范围的相关描述，正确的是（ ）。</p><ul><li>A．确认范围过程通常先于控制质量过程，二者不可同时进行</li><li>B．需求跟踪矩阵含有与需求相关的信息，包括如何确认需求</li><li>C．客户主要关注项目范围，管理层主要关注产品范围</li><li>D．符合验收标准的可交付成果应由项目经理正式签字批准</li></ul><details class="quiz" data-q="108" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：通常情况下，在确认范围前，项目团队需要先进行质量控制工作，确认范围过程通常后于控制质量过程，二者也可同时进行，因此A不正确，可作为确认范围过程输入的项目文件包括需求服院矩阵，其含有与需求相关的信息，包括如何确认需求，因此B正确（P290-292）　<span class="quiz-src">自编</span></p></details><p><a id="q109" class="quiz-anchor"></a></p><p><strong>109.</strong> 确认范围过程的输入是（ ），该输入是已经完成，并被（ ）过程检查为正确的可交付成果；确认范围的核心工具和技术包括检查和（ ）。</p><ul><li>A．核实的可交付成果、控制质量、投票</li><li>B．验收的可交付成果、控制质量、多标准决策分析</li><li>C．核实的可交付成果、管理质量、投票</li><li>D．验收的可交付成果、指导与管理项目执行、备选方案分析</li></ul><details class="quiz" data-q="109" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：确认范围过程的输入是核实的可交付成果，核实的可交付成果是指已经完成，并被控制质量过程检查为正确的可交付成果。确认范围的核心工具和技术包括检查和决策（投票），其中投票可采用一致同意、大多同意或相对多数原则（P291-292）　<span class="quiz-src">自编</span></p></details><p><a id="q110" class="quiz-anchor"></a></p><p><strong>110.</strong> 以下说法正确的是（ ）。</p><ul><li>A．可交付成果经过客户确认后就不能再变更了</li><li>B．核实的可交付成果是确认范围的输出</li><li>C．验收的可交付成果需要得到客户的正式签字确认</li><li>D．确认范围过程通常先于控制质量过程，二者也可同时进行</li></ul><details class="quiz" data-q="110" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：P251。可交付成果：是指导与管理项目工作的输出，属于原始内部交付成果。一且完成了可交付成果的第一个版本，就应该执行变更控制（P251）　<span class="quiz-src">自编</span></p></details><p><a id="q111" class="quiz-anchor"></a></p><p><strong>111.</strong> 在项目验收过程中不宜采用（ ）方法确定可交付成果是否符合需求和验收标准。</p><ul><li>A．决策</li><li>B．检查</li><li>C．观察</li><li>D．独截</li></ul><details class="quiz" data-q="111" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：，观察是收集需求的工具技术，错误　<span class="quiz-src">自编</span></p></details><p><a id="q112" class="quiz-anchor"></a></p><p><strong>112.</strong> （ ）是在确认范围中使用的工具与技术。</p><ul><li>A．决策</li><li>B．网络图</li><li>C．控制图表</li><li>D．关键路径法</li></ul><details class="quiz" data-q="112" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：可用于确认范围过程的决策技术是投票，当由项目团队和其他干系人进行验收时，使用投票来形成结论（P292）　<span class="quiz-src">自编</span></p></details><p><a id="q113" class="quiz-anchor"></a></p><p><strong>113.</strong> （ ）可用来确定可交付成果是否符合需求和验收标准。</p><ul><li>A．投票</li><li>B．观祭</li><li>C．检查</li><li>D．访谈</li></ul><details class="quiz" data-q="113" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：检查是指开展测量、审查与确认等活动，来判断工作和可交付成果是否符合需要和产品验收極准（P292）　<span class="quiz-src">自编</span></p></details><p><a id="q114" class="quiz-anchor"></a></p><p><strong>114.</strong> 关于确认范围的描述，不正确的是（ ）。</p><ul><li>A．确认范围过程贯穿项目的始终</li><li>B．确认范围可以使验收过程具有客观性</li><li>C．确认范围过程通过确认每个可交付成果来提高最终产品、服务或成果获得验收的可能性</li><li>D．确认范围过程主要关注可交付成果的正确性及是否满足质量要求</li></ul><details class="quiz" data-q="114" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：确认范围是正式验收已完成的项目可交付成果的过程。本过程的主要作用是，使验收过程具有客观性；同时通过确认每个可交付成果来提高最终产品、服务或成果获得验收的可能性控制质量过程主要关注可交付成果的正确性及是否满足质量要求（P289）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q115" class="quiz-anchor"></a></p><p><strong>115.</strong> 项目管理人员主要关注（ ）。</p><ul><li>A．项目范围</li><li>B．项目制约因素</li><li>C．产品范围丨</li><li>D．项目范围中自己参与的元素</li></ul><details class="quiz" data-q="115" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：291。项目管理人员主要关注项目制约因瓢；关心项目可交付成果是否足够和必须完成，时间、资金和资源是否足够，主要的潜在风险和预备解决的方法　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q116" class="quiz-anchor"></a></p><p><strong>116.</strong> 关于范围确认过程的描述，不正确的是（ ）。</p><ul><li>A．确认范围在项目收尾阶段</li><li>B．确认范围与控制质量可同步进行</li><li>C．干系人要确认项目风险是否太高</li><li>D．确认范围即正式验收已完成的交付成果</li></ul><details class="quiz" data-q="116" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：289。确认范围是正式验收已完成的项目可交付成果的过程。本过程的主要作用：①使验收过程具有客观性；②通过确认每个可交付成果来提高最终产品、服务或成果获得验收的可能性　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q117" class="quiz-anchor"></a></p><p><strong>117.</strong> 在项目范围管理的过程中，确认范围的输入不包括（ ）。</p><ul><li>A．项目管理计划</li><li>B．工作绩效数据</li><li>C．验收的可交付成果</li><li>D．需求跟踪矩阵</li></ul><details class="quiz" data-q="117" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：确认范围的输入包括：项目管理计划、需求文件、需求跟踪矩阵、核实的可交付成果、工作绩效数据。验收的可交付成果是范围确认的输出（P291）　<span class="quiz-src">2019 年下半年高项</span></p></details><p><a id="q118" class="quiz-anchor"></a></p><p><strong>118.</strong> 在项目范围管理中，企业管理层主要关注（ ）。</p><ul><li>A．产品的范围</li><li>B．项目范围投入产出的合理性</li><li>C．交付成果是否满足质量要求</li><li>D．项目过程的合理性</li></ul><details class="quiz" data-q="118" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：管理层主要关注项目范围：是指范围对项目的进度、资金和资源的影响，这些因素是否超过了组织承受范用，是否在投入产出上具有合理性（P290-291）　<span class="quiz-src">2020 年下半年高项</span></p></details><p><a id="q119" class="quiz-anchor"></a></p><p><strong>119.</strong> 验收的可交付成果，属于项目范围管理中（ ）过程的输出。</p><ul><li>A．定义范围</li><li>B．控制范围</li><li>C．收集需求</li><li>D．确认范围</li></ul><details class="quiz" data-q="119" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：核实的可交付成果是确认范围的输入，是控制质量的输出，验收的可交付成果是确认范围的输出（P292）　<span class="quiz-src">2020 年下半年高项</span></p></details><p><a id="q120" class="quiz-anchor"></a></p><p><strong>120.</strong> 关于确认范围的描述，正确的是（ ）。</p><ul><li>A．确认范围是在正式验收阶段才执行的过程</li><li>B．分解技术是确认范围的主要工具与技术</li><li>C．客户主要关心产品范围和可交付成果</li><li>D．确认范围强调的是结束项目所要做的流程性工作</li></ul><details class="quiz" data-q="120" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：A错误。确认范围是阶段性工作，贯穿整个项目生命周期B错误。分解技术是创建WBS的工具与技术。C正确。客户主要关心的是产品的范围，关心项目的可交付成果是否足能完成产品或服斧D错误（P291）　<span class="quiz-src">2021 年上半年高项</span></p></details><p><a id="q121" class="quiz-anchor"></a></p><p><strong>121.</strong> 在确认范围过程中，（ ）主要关注项目范围对项目进度、资金和资源的影响，这些因素是否越过了组织承受范围，是否在投入产出上具有合理性。</p><ul><li>A．客户</li><li>B．管理层</li><li>C．项目经理</li><li>D．项目团队成员</li></ul><details class="quiz" data-q="121" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：管理层主要关注项目范围：是指范围对项目的进度、资金和资源的影响，这些因素是否超过了组织承受范用，是否在投入产出上具有合理性（P290-291）　<span class="quiz-src">2021 年下半年高项</span></p></details><p><a id="q122" class="quiz-anchor"></a></p><p><strong>122.</strong> 关于范围确认和范围控制的描述，正确的是（ ）。</p><ul><li>A．当变更会对进度、成本产生较大影响时，变更申请不应该被通过</li><li>B．客户和项目团队成员往往有在当前版本中加入所有功能的意愿</li><li>C．确认范围后该项目的范围不能再更改</li><li>D．由于政府政策调整而导致项目范围的变更申请，可直接通过</li></ul><details class="quiz" data-q="122" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：A错误。变更只要通过了CCB的审批，那么按变更流程去执行即可。B正确。客户往往有在当前版本中加入所有功能和特征的意愿，这对于项目来说是一种潜在的风险，会给组织和客户带来危害和损失（P290-291）　<span class="quiz-src">2022 年下半年高项</span></p></details><p><a id="q123" class="quiz-anchor"></a></p><p><strong>123.</strong> 关于确认范围的描述，不正确的是（ ）。</p><ul><li>A．确认范围的作用之一是确保验收过程具有客观性</li><li>B．确认范围过程通常先于控制质量过程，二者也可同时进行</li><li>C．在确认范围时，要检查可交付成果是否有明确的质量标准</li><li>D．管理层、客户、项目管理人员在确认范围时的关注点有所不同</li></ul><details class="quiz" data-q="123" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：通常情况下，在确认范围前，项目团队需要先进行质量控制工作，例如，在确认软件项目的范围之前，需要进行系统测试等工作，以确保确认工作的顺利完成（P290）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q124" class="quiz-anchor"></a></p><p><strong>124.</strong> （ ）含有与需求相关的信息，包括如何确认需求，在确认范围中被使用</p><ul><li>A．需求跟踪矩阵</li><li>B．需求文件：</li><li>C．质量报告</li><li>D．经验教训登记册</li></ul><details class="quiz" data-q="124" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：可作为确认范围过程输入的项目文件主要包括：“(1)需求文件：将需求与实际结果比较，以决定是否有必要进行变更，采取纠正措施或预防措施（P291）　<span class="quiz-src">2023 年下半年高项第 1 批</span></p></details><p><a id="q125" class="quiz-anchor"></a></p><p><strong>125.</strong> 范围确认中，（ ）关心项目的可交付成果是否足够完成产品或服务。</p><ul><li>A．项目管理人员</li><li>B．客户</li><li>C．项目团队成员</li><li>D．高层领导</li></ul><details class="quiz" data-q="125" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：确认范围主要是项目干系人对项目的范围进行确认和接受的工作。每个人对项目范围所关注的方面是不同的：“(1)管理层主要关注项目范围；是指范围对项目的进度、资金和资源的影响，这些因素是否超过了组织承受范围，是否在投入产出上具有合理性（P290-291）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q126" class="quiz-anchor"></a></p><p><strong>126.</strong> 由客户或者发起人正式签字批准的文件是（ ）</p><ul><li>A．核实的可交付成果</li><li>B．工作绩效信息</li><li>C．验收的可交付成果</li><li>D．可交付成果</li></ul><details class="quiz" data-q="126" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：验收的可交付成果：符合验收标准的可交付成果应该由客户或发起人正式签字批准。应该从客户或发起人那里获得正式文件，证明干系人对项目可交付成果的正式验收（P292）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q127" class="quiz-anchor"></a></p><p><strong>127.</strong> 关于确认范围管理过程的叙述，正确的是（ ）。</p><ul><li>A．项目团队成员主要关注项目范围中自己参与的元素和负责的元素</li><li>B．项目实施单位的管理层主要关注产品或服务范围，客户主要关注项目制约因素</li><li>C．确认范围过程的作用是为所要交付的内容提供架构</li><li>D．符合验收标准的可交付成果应由项目经理正式签字批准</li></ul><details class="quiz" data-q="127" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：管理层主要关注项目范围：是指范围对项目的进度、资金和资源的影响，这些因素是否超过了组织承受范围，是否在投入产出上具有合理性（P290-291）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q128" class="quiz-anchor"></a></p><p><strong>128.</strong> 确认范围过程依据（ ）过程形成的范围基准和（ ）过程形成的工作绩效数据和其他信息，对完成的成果进行验收，并将工作绩效信息输出给（ ）过程。</p><ul><li>A．定义范围、管理项目知识、监控项目工作</li><li>B．创建WBS、指导与管理项目执行、监控项目工作</li><li>C．创建WBS、管理项目知识、结束项目或阶段</li><li>D．定义范围、指导与管理项目执行、结束项目或阶段</li></ul><details class="quiz" data-q="128" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：范困管理计划规划范围 需求管理计划管理 验收的可交付成果 结束项目或求文件 阶段需求跟踪矩阵收集需求 变更请求 实随整体变更控制范团基准创建wBS工作绩效信息 盈控项目工作确认范围工作绩效数据指导与管理项目执行核实的可交付成果 需求文件（更新）控制质量 需求跟踪矩阵（更新）经验教训置记册（更新）质量报告管理质量项目文件经验教训登记册管理项目如识（P289-290）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q129" class="quiz-anchor"></a></p><p><strong>129.</strong> 确认范围的一般步骤不包括（ ）。</p><ul><li>A．识别范围确认需要哪些投入</li><li>B．确定需要进行范围确认的时间</li><li>C．确定可交付成果的正确性</li><li>D．确定被接受的标准和要素</li></ul><details class="quiz" data-q="129" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：确认范围的步骤：①确定需要进行范围确认的时间；②识别范围确认需要哪些投入；③确定范围正式被接受的标准和要素；④确定范围确认公议的组织步骤；⑤组织范围确认公议（P290）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q130" class="quiz-anchor"></a></p><p><strong>130.</strong> 以下关于范围变更的说法错误的是（ ）。</p><ul><li>A．范围变更是不可避免的，范围变更如果不加以控制可能引起范围楚延</li><li>B．客户对产品的需求发生变化其实就是一种范围变更</li><li>C．范围变更过程中应多让客户参与，以免后期进行范围确认时发生问题</li><li>D．范围变更控制流程与整体变更控制流程应分开设计，确保项目发生范围变更时遵从范围变更控制流程，由于范围变更引起了其他变更时遵从整体变更流程</li></ul><details class="quiz" data-q="130" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：293。控制范围过程应该与其他项目管理知识领域的控制过程协调开展。D错误　<span class="quiz-src">自编</span></p></details><p><a id="q131" class="quiz-anchor"></a></p><p><strong>131.</strong> 控制范围过程的输入包括范围基准、绩效测量基准和（ ），其中（ ）用于与实际结果比较决定是否需要变更或采取纠正、预防措施；（ ）包括收到的变更请求数量、接受的变更请求数量等信息。</p><ul><li>A．工作绩效数据、范围基准、工作绩效数据</li><li>B．工作绩效信息、绩效测量基准、工作绩效信息</li><li>C．工作绩效数据、绩效测量基准、工作绩效信息</li><li>D．工作绩效信息、范围基准、工作绩效数据</li></ul><details class="quiz" data-q="131" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制范围的输入包括范围基准、绩效测量基准和工作绩效数据。其中范围基准和绩效测量基准均可与实际结果比较，以法定是否有必要进行变更、采取纠正措施或预防措施；工作绩效数据包括收到的变更请求的数量，接受的变更请求的数量或者核实、确认和完成的可交付成果的数量（P293-294）　<span class="quiz-src">自编</span></p></details><p><a id="q132" class="quiz-anchor"></a></p><p><strong>132.</strong> 在控制项目范围时，不需要用到（ ）。</p><ul><li>A．工作绩效报告</li><li>B．需求管理计划</li><li>C．WBS词典</li><li>D．配置管理计划</li></ul><details class="quiz" data-q="132" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制项目范围的输入：1项目管理计划（范围管理计划、盖求管理计划、变更管理计划、配置管理计划、范围基准、绩效测量基准）;2.项目文件（需求文件、雷求跟踪矩阵、经验教训登记册）;3.工作绩效数据；4.组织过程资产（P293-294）　<span class="quiz-src">自编</span></p></details><p><a id="q133" class="quiz-anchor"></a></p><p><strong>133.</strong> （ ）属于项目范围控制使用的工具和技术。</p><ul><li>A．偏差分析</li><li>B．实验设计</li><li>C．敏感性分析</li><li>D．回归分析</li></ul><details class="quiz" data-q="133" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制范围工具与技术：数据分析（偏差分析、趋势分析）（P294）　<span class="quiz-src">自编</span></p></details><p><a id="q134" class="quiz-anchor"></a></p><p><strong>134.</strong> （ ）是审查项目绩效随时间的变化情况，以判断绩效是正在改善还是正在恶化。</p><ul><li>A．偏差分析</li><li>B．趋势分析</li><li>C．检查</li><li>D．挣值管理</li></ul><details class="quiz" data-q="134" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：趋势分析：旨在审查项目绩效随时间的变化情况，以判断绩效是正在改普还是正在恶化（P294）　<span class="quiz-src">自编</span></p></details><p><a id="q135" class="quiz-anchor"></a></p><p><strong>135.</strong> 关于控制范围的相关描述，不正确的是（ ）。</p><ul><li>A．控制范围的数据分析包括偏差分析和趋势分析</li><li>B．偏差分析通过将基准与实际结果比较，确定偏差是否需采取纠正或预防措施</li><li>C．趋势分析旨在审查项目绩效随时间的变化，判断绩效是改善还是恶化</li><li>D．范围基准偏差轻微时，项目经理可以根据情况自行调整，无需走变更流程</li></ul><details class="quiz" data-q="135" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「范围基准偏差轻微时，项目经理可以根据情况自行调整，无需走变更流程」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q136" class="quiz-anchor"></a></p><p><strong>136.</strong> 下面属于项目范围控制活动的是（ ）。</p><ul><li>A．对项目的绩效情况进行分析，确定是否偏离设定的范围基准</li><li>B．对详细的范围说明书进行评审，提交客户签字确认</li><li>C．与客户充分沟通以获取项目的详细需求</li><li>D．与客户开展审查或检查活动，判断工作和交付成果是否符合设定的标准</li></ul><details class="quiz" data-q="136" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「对项目的绩效情况进行分析，确定是否偏离设定的范围基准」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q137" class="quiz-anchor"></a></p><p><strong>137.</strong> 不会影响项目范围控制过程的活动是（ ）。</p><ul><li>A．小问题无须汇报项目经理自行解决</li><li>B．项目干系人提出的需求都应被接受</li><li>C．团队成员加班加点完成项目任务</li><li>D．项目团队成员主动改善系统功能</li></ul><details class="quiz" data-q="137" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「团队成员加班加点完成项目任务」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q138" class="quiz-anchor"></a></p><p><strong>138.</strong> 项目组成员小李常驻用户现场开发，经常收到用户提出的新需求。针对有些新需求以及部分修改工作量很小的需求，小李直接进行了修改，用户对此非常满意，但却遭到项目经理的批评，这是因为（ ）。</p><ul><li>A．小李没有把项目经理放在眼里</li><li>B．项目经理认为小李收了用户的好处</li><li>C．小李的行为可能造成项目范田蔓延</li><li>D．小李所作的工作没有给项目带来经济效益</li></ul><details class="quiz" data-q="138" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「小李的行为可能造成项目范田蔓延」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q139" class="quiz-anchor"></a></p><p><strong>139.</strong> 某项目在执行过程中，软件的需求基线已经确定后，客户需要增加新的功能，但该需求变更会对已经完成系统的稳定性有较大影响。作为项目负责人处理这些需求变更，下列（ ）做法是不合适的</p><ul><li>A．利用原型法给用户提供预览，以帮助准确把握用户的真实需求</li><li>B．可以跟客户说不，并与其商议在后续项目或下一版本中满足他们的要求</li><li>C．乘承“客户至上”的原则，召集有关人员开始变更工作，满足客户的要求</li><li>D．利用在项目初期文档化的视图、范围、限制，与变更项比较，决定是否采用此项变更</li></ul><details class="quiz" data-q="139" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「乘承“客户至上”的原则，召集有关人员开始变更工作，满足客户的要求」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q140" class="quiz-anchor"></a></p><p><strong>140.</strong> 在项目开发阶段，用需求跟踪矩阵进行跟踪时发现，某交付成果在需求跟踪矩阵里并未找到出处，这种情况一般是（ ）所造成。</p><ul><li>A．确认范围没做好</li><li>B．范围登延</li><li>C．范围镀金</li><li>D．定义范围有问题</li></ul><details class="quiz" data-q="140" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「范围镀金」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q141" class="quiz-anchor"></a></p><p><strong>141.</strong> 测试人员在测试某一功能时，发现该功能在需求说明书里没有，他接下来正确的做法是（ ）</p><ul><li>A．在需求说明书中补充该功能</li><li>B．汇报项目经理，让其查明原因</li><li>C．找开发人员沟通，让其删除该功能</li><li>D．找用户沟通，该功能是否需要</li></ul><details class="quiz" data-q="141" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「汇报项目经理，让其查明原因」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q142" class="quiz-anchor"></a></p><p><strong>142.</strong> 某项目已制定了详细的范围说明书，并完成了WBS分解。在项目执行过程中，项目经理在进行下一周工作安排的时候，发现WBS中遗漏了一项重要的工作，那么接下来他应该首先（ ）</p><ul><li>A．组织项目组讨论，修改WBS</li><li>B．修改项目管理计划，并重新评审</li><li>C．汇报给客户，与其沟通，重新编写项目文档</li><li>D．填写项目变更申请，对产生的工作量进行估算，等待变更委员会审批</li></ul><details class="quiz" data-q="142" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「填写项目变更申请，对产生的工作量进行估算，等待变更委员会审批」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q143" class="quiz-anchor"></a></p><p><strong>143.</strong> 在项目实施过程中，客户提出新的功能需求时，正确的做法是（ ）</p><ul><li>A．由项目经理发起变更管理流程来决定是否增加该功能</li><li>B．由项目经理根据项目执行情况来决定是否增加该功能</li><li>C．由实施人员根据经验判断来决定是否增加该功能</li><li>D．由项目的投资人离洪决定是否增加该功能</li></ul><details class="quiz" data-q="143" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「由项目经理发起变更管理流程来决定是否增加该功能」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q144" class="quiz-anchor"></a></p><p><strong>144.</strong> 公司上个月取消了由张工管理的视频游戏项目的需求定义文件和范围说明。现在公司要求将该项目成果变成可在个人电视及计算机上玩的交互游戏。这至少（ ）。</p><ul><li>A．需要修改项目既定的由WBS定义的范围</li><li>B．导致所有项目基准的改变</li><li>C．导致成本、时间、质量和其他目标的调整</li><li>D．会得到一个教训</li></ul><details class="quiz" data-q="144" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「需要修改项目既定的由WBS定义的范围」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q145" class="quiz-anchor"></a></p><p><strong>145.</strong> 如果产品范围做了变更，下一步应该调整（ ）。</p><ul><li>A．项目范围</li><li>B．进度表</li><li>C．SOW</li><li>D．质量基准</li></ul><details class="quiz" data-q="145" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「项目范围」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q146" class="quiz-anchor"></a></p><p><strong>146.</strong> 在项目执行过程中，项目经理反复与关键干系人沟通并强调已批准的项目范围。进行这项活动的主要目的是（ ）。</p><ul><li>A．防止范围蔓延，确保项目在既定边界内完成</li><li>B．获取干系人对项目可交付成果的正式验收</li><li>C．为创建详细的工作分解结构(WBS)收集输入</li><li>D．识别并记录干系人的所有潜在需求</li></ul><details class="quiz" data-q="146" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：防止范围整延”是核心目的。通过强调范围，可以确保所有干系人对项目边界（做什么、不做什么）有清晰、一致的理解，从面减少因期望不一致或盖求模糊而导致的未经控制的变更（即范围蔓延）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q147" class="quiz-anchor"></a></p><p><strong>147.</strong> 某项目执行中，为了客户满意度，开发团队在收到来自客户的需求细节和新需求后立即执行，导致进度延误1个月，成本超支20%，该现象被称为（ ）。</p><ul><li>A．弹性范围</li><li>B．范围蔓延</li><li>C．镀金</li><li>D．范围注水</li></ul><details class="quiz" data-q="147" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：未经控制的产品或项目范围的扩大（未对时间、成本和资源做相应调整）被称为范围蔓延（P293）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q148" class="quiz-anchor"></a></p><p><strong>148.</strong> （ ）属于控制范围的活动。</p><ul><li>A．与客户仔细讨论项目范围说明书，并请客户签字</li><li>B．当客户提出新的需求时，说服用户放弃新的需求</li><li>C．确认项目范围是否覆盖了需要完成的产品或服务进行的所有活动</li><li>D．确认每项工作是否有明确的质量标准</li></ul><details class="quiz" data-q="148" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「当客户提出新的需求时，说服用户放弃新的需求」，原解析未给课本依据　<span class="quiz-src">2018 年上半年高项</span></p></details><p><a id="q149" class="quiz-anchor"></a></p><p><strong>149.</strong> （ ）是控制范围常用的工具和技术。</p><ul><li>A．引导式研讨会</li><li>B．产品分析</li><li>C．偏差分析</li><li>D．标杆对照</li></ul><details class="quiz" data-q="149" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：偏差分析：用于将基准与实际结果进行比较，以确定偏差是否处于临界值区间内或是否有必要采取纠正或预防措施趋势分析：旨在审查项目绩效随时间的变化情况，以判断绩效是正在改善还是正在恶化（P294）　<span class="quiz-src">2018 年下半年高项</span></p></details><p><a id="q150" class="quiz-anchor"></a></p><p><strong>150.</strong> 关于范围控制的描述，正确的是（ ）。</p><ul><li>A．控制进度是控制范围的一种有效的方式</li><li>B．项目执行组织本身发生变化不会引起范围变更</li><li>C．范围变更控制必须和其他控制过程综合在一起</li><li>D．政府政策的变化不可以成为范围变更的理由</li></ul><details class="quiz" data-q="150" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「范围变更控制必须和其他控制过程综合在一起」，原解析未给课本依据　<span class="quiz-src">2019 年上半年高项</span></p></details><p><a id="q151" class="quiz-anchor"></a></p><p><strong>151.</strong> 项目进入设计阶段时，GB/T22239《信息安全技术网络安全等级保护基本要求》已经升级版本，而项目需求是按旧版本策划的。（ ）直接影响项目进度。</p><ul><li>A．提高需求评审频率</li><li>B．执行项目范围变更</li><li>C．与项目干系人沟通</li><li>D．重新进行成本估算</li></ul><details class="quiz" data-q="151" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「执行项目范围变更」，原解析未给课本依据　<span class="quiz-src">2021 年上半年高项</span></p></details><p><a id="q152" class="quiz-anchor"></a></p><p><strong>152.</strong> （ ）包括收到的变更请求的数量，接受的变更请求的数量或者确认和完成的可交付成果的数量控制范围过程产生的（ ）包括收到的变更的分类、识别的范围偏差和原因、偏差对进度和成本的影响，以及对将来范围绩效的预测。</p><ul><li>A．工作绩效报告；工作绩效信息</li><li>B．工作绩效数据；工作绩效信息</li><li>C．工作绩效信息；工作绩效报告</li><li>D．工作绩效数据；工作绩效报告</li></ul><details class="quiz" data-q="152" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：工作绩效数据：包括已完成的工作、关键绩效指标(KPI)、技术绩效测量结果、进度活动的实际开始日期和完成日期、已完成的故事点、可交付成果状态、进度进展情况、变更请求的数量、缺陷的数量、实际发生的成本、实际持续时间等工作绩效信息：包括收到的变更的分类、识别的范围偏差和原因、偏差对进度和成本的影响以及对将来范围绩效的预测（P294）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q153" class="quiz-anchor"></a></p><p><strong>153.</strong> 在控制范围过程中，可更新的主要项目文件是（ ）。①需求文件②问题日志③需求跟踪矩阵④经验教训登记册⑤绩效测量基准</p><ul><li>A．①②③</li><li>B．②③⑤</li><li>C．③④⑤</li><li>D．①③④</li></ul><details class="quiz" data-q="153" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：可在控制范围过程更新的项目文件主要包括：蛋求文件、需求跟踪矩阵、经验教训登记册（P295）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q154" class="quiz-anchor"></a></p><p><strong>154.</strong> 控制范围”过程中，通常会使用到的项目管理计划组件包括（ ）①绩效测量基准；②需求管理计划；③变更管理计划；④需求跟踪矩阵；⑤范围基准；⑥变更请求</p><ul><li>A．②④⑤⑥</li><li>B．346</li><li>C．①②③⑤</li><li>D．℃③④⑥</li></ul><details class="quiz" data-q="154" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：控制范围中使用的项目管理计划组件主要包括：●范田管理计划：记录了如何控制项目和产品范围。●需求管理计划：记录了如何管理项目需求（P293）　<span class="quiz-src">2026 年高项第 2 批</span></p></details></div>`,1)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};